var n=`0370-zurcher-geschnetzeltes`;var i=`world-0370`;var a=`CH`;var o=`western-europe`;var s=4;var r=29;var u={en:`Zürcher Geschnetzeltes`,ua:`Цюрихське рагу з телятини`};var l={en:`A traditional Switzerland dish made with veal, button mushroom, yellow onion, heavy cream. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Швейцарія. Основні інгредієнти: телятина, печериця, жовта цибуля, вершки високої жирності. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 9 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 9 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:9,i:[[`veal`,650,`g`],[`unsalted-butter`,60,`g`],[`button-mushroom`,250,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 6 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 6 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:6,i:[[`yellow-onion`,150,`g`],[`dry-white-wine`,150,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 12 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 12 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:12,i:[[`heavy-cream`,330,`ml`],[`beef-stock`,160,`ml`],[`lemon-juice`,20,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,19,`g`],[`table-salt`,null,`to_taste`]]}];var m={slug:n,id:i,country:`CH`,region:o,servings:4,minutes:29,title:u,text:l,steps:d};export{a as country,m as default,i as id,r as minutes,o as region,s as servings,n as slug,d as steps,l as text,u as title};